local config = {
  ui_story_31380401_1_dialog_content = "What a great day.",
  ui_story_31380401_2_dialog_content = "No dangerous Eclipsites or difficult quests.",
  ui_story_31380401_3_dialog_content = "This is the best time to take a nap in my room.",
  ui_story_31380401_4_dialog_content = "It's also a good time to exercise outdoors.",
  ui_story_31380401_5_dialog_content = "Hi, Siobhan.",
  ui_story_31380401_X5_dialog_content = "Oh, PlayerName, Vice, hello!",
  ui_story_31380401_X6_dialog_content = "What are you talking about?",
  ui_story_31380401_6_dialog_content = "We were discussing where we could go to relax. Do you have any recommendations?",
  ui_story_31380401_7_dialog_content = "Relax...? Hmm... I think it's great to relax in a cafe.",
  ui_story_31380401_8_dialog_content = "Work-life balance is the key to maintaining good efficiency.",
  ui_story_31380401_9_dialog_content = "I think it's great to go to the bar, too, I can sip on fruity soda while listening to music.",
  ui_story_31380401_10_dialog_content = "Most of the Aurorians here love to go to the bar. I hope...",
  ui_story_31380401_11_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_31380401_12_dialog_content = "What was that?!",
  ui_story_31380401_13_dialog_content = "Sounds like it came from the bar! Something must have dropped to the floor.",
  ui_story_31380401_14_dialog_content = "Speak of the devil. Let's go take a look!",
  ui_story_31380401_15_dialog_content = "...!",
  ui_story_31380401_16_dialog_content = "<color=#e8d9bb>Inside the Bar</color>",
  ui_story_31380401_17_dialog_content = "... and the cat jumped onto my face. I lost balance and tripped over. That's what happened...",
  ui_story_31380401_18_dialog_content = "Korgon... what are you talking about?",
  ui_story_31380401_19_dialog_content = "You fell onto the ground because your left foot tripped over your right foot.",
  ui_story_31380401_20_dialog_content = "Ah... Are you okay?",
  ui_story_31380401_21_dialog_content = "Oh... who are you? You have so many eyes!",
  ui_story_31380401_22_dialog_content = "Also, why are there so many kittens running in circles in the air?",
  ui_story_31380401_23_dialog_content = "You reek of alcohol... Are you drunk?",
  ui_story_31380401_24_dialog_content = "Alcohol? Oh... I did have a little...",
  ui_story_31380401_25_dialog_content = "But that was last night...",
  ui_story_31380401_26_dialog_content = "The Boss and the others work so hard.",
  ui_story_31380401_27_dialog_content = "We finally finished, but there wasn't even enough time to comb the cat's fur at this hour.",
  ui_story_31380401_28_dialog_content = "Yeah! Our superiors don't even care how much burden they put on our lives.",
  ui_story_31380401_29_dialog_content = "I guess you can say that... Hold on, who are you? Why haven't I seen you before?",
  ui_story_31380401_30_dialog_content = "I'm just a worker who isn't worth mentioning, and I'm being exploited just like you.",
  ui_story_31380401_31_dialog_content = "Eh... Do you want to take a rest?",
  ui_story_31380401_32_dialog_content = "Your dark circles look so exaggerated.",
  ui_story_31380401_33_dialog_content = "I've been working overtime for nearly twenty days in a row now...",
  ui_story_31380401_34_dialog_content = "I can only heal this pain with a cup of hot and healthy tea in a thermos cup.",
  ui_story_31380401_35_dialog_content = "Do you want a cup too? It's great for relieving mental fatigue.",
  ui_story_31380401_36_dialog_content = "Is it that effective? I'll try some too, then. Thank you.",
  ui_story_31380401_37_dialog_content = "Hmm? Why does it smell funny?",
  ui_story_31380401_38_dialog_content = "Well, it's a healthy tea, so there are many herbs inside it.",
  ui_story_31380401_39_dialog_content = "There are even vitamins produced by Illumina in it, so it's absolutely safe.",
  ui_story_31380401_40_dialog_content = "I'll give it a try then.",
  ui_story_31380401_41_dialog_content = "Ahhh! It's so spicy! Why is it so spicy?!",
  ui_story_31380401_42_dialog_content = "Water! I need water!",
  ui_story_31380401_43_dialog_content = "Spicy? Hold on, take this.",
  ui_story_31380401_44_dialog_content = "Glug, glug, glug... Ahhh...",
  ui_story_31380401_45_dialog_content = "I'm saved! Thank you...",
  ui_story_31380401_46_dialog_content = "The water tastes funny... Burp!",
  ui_story_31380401_47_dialog_content = "W-what's going on?",
  ui_story_31380401_48_dialog_content = "This is... Oh no! I took the wrong cup!",
  ui_story_31380401_49_dialog_content = "This cup contains a special 96% distilled liquor made in Northland...",
  ui_story_31380401_50_dialog_content = "I was fine when I drank it though...",
  ui_story_31380401_51_dialog_content = "Well... that's what happened. I can't remember what that person looks like anymore... Burp!",
  ui_story_31380401_52_dialog_content = "Oh, I need to... take a nap...",
  ui_story_31380401_53_dialog_content = "Korgon fell asleep...",
  ui_story_31380401_54_dialog_content = "Just let him lie here until he sobers up.",
  ui_story_31380401_55_dialog_content = "But there's actually someone who can drink distilled liquor like water... Things will get worse if we don't do anything about it.",
  ui_story_31380401_56_dialog_content = "It's probably best to find this person and make things clear directly. At least there won't be other victims like Korgon.",
  ui_story_31380401_57_dialog_content = "I can't agree more...",
  ui_story_31380401_58_dialog_content = "Korgon didn't mention that person's appearance. Who could it be?",
  ui_story_31380401_59_dialog_content = "...",
  ui_story_31380401_60_dialog_content = "Siobhan, you look very concerned.",
  ui_story_31380401_61_dialog_content = "...! No, i-it's nothing.",
  ui_story_31380401_62_dialog_content = "I just analyzed some possibilities. Do you want to hear them?",
  ui_story_31380401_63_dialog_content = "Siobhan, what do you think?",
  ui_story_31380401_64_dialog_content = "I-indeed. I thought of some possibilities.",
  ui_story_31380401_65_dialog_content = "Tell me about them.",
  ui_story_31380401_66_dialog_content = "Well... For one, this person is a good drinker, so they probably visit the bar often.",
  ui_story_31380401_67_dialog_content = "Second, Korgon doesn't recognize this person, so it should be someone from a faction he doesn't have many dealings with.",
  ui_story_31380401_68_dialog_content = "Finally, this person recommended a very unique way of adding chili sauce to barbecue.",
  ui_story_31380401_69_dialog_content = "In summary, I think we should start by investigating the members of Rediesel Wrench first.",
  ui_story_31380401_70_dialog_content = "As expected of a reliable researcher. My thinking has become clear now!",
  ui_story_31380401_71_dialog_content = "Let's go and ask the members of Rediesel Wrench then.",
  ui_story_31380401_72_dialog_content = "Yeah, let's go.",
  ui_story_31380401_73_dialog_content = "Phew...",
  ui_story_31380401_74_dialog_content = "<color=#e8d9bb>Sinsa's Room</color>",
  ui_story_31380401_75_dialog_content = "You're asking me if I went to the bar yesterday?",
  ui_story_31380401_76_dialog_content = "Of course not!",
  ui_story_31380401_77_dialog_content = "Where did you go then? Can anyone prove it?",
  ui_story_31380401_78_dialog_content = "Hey, you sound quite arrogant, huh?",
  ui_story_31380401_79_dialog_content = "I go wherever I want!",
  ui_story_31380401_80_dialog_content = "What's that got to do with you?",
  ui_story_31380401_81_dialog_content = "N-no, that's not what we meant.",
  ui_story_31380401_82_dialog_content = "It's just that an unknown person got Korgon completely drunk, and I want to rule you out.",
  ui_story_31380401_83_dialog_content = "Tsh. Fine then. I was incredibly bored last night, so I went out to rob some people with my pals.",
  ui_story_31380401_84_dialog_content = "Huh...?",
  ui_story_31380401_85_dialog_content = "What's so surprising?",
  ui_story_31380401_86_dialog_content = "Joanie Boom, Regina, and the others were with me, so you can ask them if you don't believe me.",
  ui_story_31380401_87_dialog_content = "If I remember correctly, I robbed the caravan that's transporting goods to Lumopolis.",
  ui_story_31380401_88_dialog_content = "Those people are so rich! I made so much in this trade!",
  ui_story_31380401_89_dialog_content = "Um, I don't think you can call that a trade, right...",
  ui_story_31380401_90_dialog_content = "Anyway, I've told you everything you want to know.",
  ui_story_31380401_91_dialog_content = "You should ask someone else.",
  ui_story_31380401_92_dialog_content = "I see...",
  ui_story_31380401_93_dialog_content = "Do you know anyone who is especially good at drinking?",
  ui_story_31380401_94_dialog_content = "Oh yeah, I almost forgot to ask you that.",
  ui_story_31380401_95_dialog_content = "Someone good at drinking? There are way too many people. It'll take you days to investigate them all.",
  ui_story_31380401_96_dialog_content = "That's fine. We can deal with the rest.",
  ui_story_31380401_97_dialog_content = "<color=#e8d9bb>Several hours later...</color>",
  ui_story_31380401_98_dialog_content = "Of course I was exercising last night.",
  ui_story_31380401_99_dialog_content = "I have to train at all times to become the best to lead Rediesel Wrench.",
  ui_story_31380401_100_dialog_content = "Me? Boss made a mess with his car again... I spent all the time fixing it from last night until this morning.",
  ui_story_31380401_101_dialog_content = "Your questions are so strange.",
  ui_story_31380401_102_dialog_content = "Wow, it's been ages. I'm so tired... Vice, how many have we asked?",
  ui_story_31380401_103_dialog_content = "That's 12 people if we count Fleur.",
  ui_story_31380401_104_dialog_content = "How many people are left?",
  ui_story_31380401_105_dialog_content = "There are still... 26 of them.",
  ui_story_31380401_106_dialog_content = "... Why are all these people so good at drinking!",
  ui_story_31380401_107_dialog_content = "We can't keep investigating like this...",
  ui_story_31380401_108_dialog_content = "Caelestite, what if we forget about this incident for now?",
  ui_story_31380401_109_dialog_content = "Korgon is the only victim so far, and there were no major losses.",
  ui_story_31380401_110_dialog_content = "I think we should put up a notice in the bar to remind everyone. That'll be more effective and efficient than investigating aimlessly.",
  ui_story_31380401_111_option_content = "I guess... you're right.",
  ui_story_31380401_112_dialog_content = "We're just wearing ourselves out for no reason like this.",
  ui_story_31380401_113_dialog_content = "Indeed...",
  ui_story_31380401_114_option_content = "That's it. I don't want to investigate this anymore...",
  ui_story_31380401_115_dialog_content = "Let's get some good rest first...",
  ui_story_31380401_116_dialog_content = "Let's do that then. We'll rest tonight and then consider putting up a notice tomorrow...",
  ui_story_31380401_117_dialog_content = "Oh! If it isn't our super-rare researcher Sio!",
  ui_story_31380401_118_dialog_content = "Why are you here...!!!",
  ui_story_31380401_119_dialog_content = "Well, I saw you looking for sobering medicine in the bar last night and I thought you were drunk!",
  ui_story_31380401_120_dialog_content = "But here you are, full of energy!",
  ui_story_31380401_121_dialog_content = "As expected of Sio who is immune to the effects of alcohol!",
  ui_story_31380401_122_dialog_content = "Huh...?!",
  ui_story_31380401_123_dialog_content = "P-Please don't make up stuff...!",
  ui_story_31380401_124_dialog_content = "Last night, in the bar, searching for sobering medicine...?",
  ui_story_31380401_125_dialog_content = "Listen to me...",
  ui_story_31380401_X125_dialog_content = "And you're completely immune to the effects of alcohol?!",
  ui_story_31380401_126_dialog_content = "So it was you?!",
  ui_story_31380401_127_dialog_content = "We trusted you and followed you all day to ask questions.",
  ui_story_31380401_128_dialog_content = "Miss Siobhan, who looks so mature and reliable, is actually...",
  ui_story_31380401_129_dialog_content = "Is actually a liar!",
  ui_story_31380401_130_dialog_content = "It's not such a big deal... or is it?",
  ui_story_31380401_131_dialog_content = "Ah... I admit I didn't deal with this in the best way.",
  ui_story_31380401_132_dialog_content = "I searched for sobering medicine for most of the day to no avail, and you still managed to find out...",
  ui_story_31380401_133_dialog_content = "I'll do everything I can to compensate you for the losses I caused.",
  ui_story_31380401_134_dialog_content = "I'll also talk to Korgon about this as well.",
  ui_story_31380401_135_dialog_content = "Whether I have to apologize or pay compensation, I won't avoid it as long as it's my responsibility.",
  ui_story_31380401_136_dialog_content = "This is the code I follow in both work and life.",
  ui_story_31380401_137_dialog_content = "Sigh... forget it. It's not like there were any major losses. Just remember to apologize to Korgon.",
  ui_story_31380401_138_dialog_content = "Yea, so don't make such a serious expression, Sio.",
  ui_story_31380401_139_dialog_content = "Cheer up! I just found an ancient technology and was about to take it to you.",
  ui_story_31380401_140_dialog_content = "Really? Show me!",
  ui_story_31380401_141_dialog_content = "Oh! This thing has quite the history!",
  ui_story_31380401_142_dialog_content = "According to my estimation, it should be a device that contains ancient scientific and technological data. We will need special equipment to decode it...",
  ui_story_31380401_143_dialog_content = "Good eye, Sio! You understood with one look!",
  ui_story_31380401_144_dialog_content = "So what is it?",
  ui_story_31380401_145_dialog_content = "It is a device that contains ancient video games!",
  ui_story_31380401_146_dialog_content = "...!?",
  ui_story_31380401_147_dialog_content = "I'll leave the analysis to you, my dear Sio. I know that's what you do the best.",
  ui_story_31380401_148_dialog_content = "Remember to finish the game in three days, then write me a review. I'm off now, see ya!",
  ui_story_31380401_149_dialog_content = "...",
  ui_story_31380401_150_dialog_content = "This quest is really... Miss Siobhan?!",
  ui_story_31380401_151_dialog_content = "PlayerName! Miss Siobhan has fainted!",
  ui_story_31380401_152_dialog_content = "Siobhan? Siobhan!!!",
  ui_story_31380601_1_dialog_content = "It's thanks to your help that we could finish today's mission so smoothly.",
  ui_story_31380601_2_dialog_content = "It was nothing. I barely lifted a finger.",
  ui_story_31380601_3_dialog_content = "How about we go for a drink after I report to Officer Gronru?",
  ui_story_31380601_4_dialog_content = "I don't know about that...",
  ui_story_31380601_5_dialog_content = "You're blushing right now because you think I just asked you out on a date, right? Ah, to be young and innocent again...",
  ui_story_31380601_6_dialog_content = "If my face changed color just now, it's more likely to have been from fear than embarrassment.",
  ui_story_31380601_7_dialog_content = "After all, everyone knows you can even down Northland's special 96% distilled liquor like it's water.",
  ui_story_31380601_8_dialog_content = "Now, that's an exaggeration... I just like a little drop now and then to take me to my happy place.",
  ui_story_31380601_9_dialog_content = "\"A little drop\" might be the understatement of the century...",
  ui_story_31380601_10_dialog_content = "How about we just grab a cup of black coffee then?",
  ui_story_31380601_11_dialog_content = "Coffee, tea, juice... I'm good with any of them.",
  ui_story_31380601_12_dialog_content = "It's a date, then.",
  ui_story_31380601_13_dialog_content = "Huh? That's...",
  ui_story_31380601_14_dialog_content = "It's Lilliam. They just came out of Officer Gronru's office.",
  ui_story_31380601_15_dialog_content = "They're dressed differently from usual.",
  ui_story_31380601_16_dialog_content = "Probably because of the upcoming concert.",
  ui_story_31380601_17_dialog_content = "I know you'll do great. Make the Research Lab proud!",
  ui_story_31380601_18_dialog_content = "Command acknowledged. Lilliam No. 1 wants to gain prestige for the Research Lab.",
  ui_story_31380601_19_dialog_content = "Translating and converting: Lilliam No. 1 will take one of the first three places in the concert auditions.",
  ui_story_31380601_20_dialog_content = "And No. 2 will also get into the top three!",
  ui_story_31380601_21_dialog_content = "No. 2 has prepared an all-new idol style, just for this concert~ Aiming straight for your heart!☆",
  ui_story_31380601_22_dialog_content = "No. 2, what's wrong with your eye? Are you feeling okay?",
  ui_story_31380601_23_dialog_content = "I'm winking! Everyone knows that a wink can convey the mysterious silent language of an idol's charm.❤",
  ui_story_31380601_24_dialog_content = "Warning! Officer Gronru is experiencing a facial spasm.",
  ui_story_31380601_25_dialog_content = "Translating and converting: The corner of Officer Gronru's mouth is twitching.",
  ui_story_31380601_26_dialog_content = "Hypothesizing... Officer Gronru cannot understand the meaning of No. 2's wink.",
  ui_story_31380601_27_dialog_content = "Alright, you lot go and register. Make sure you're well-prepared.",
  ui_story_31380601_28_dialog_content = "Command acknowledged. Program launched... Registering.",
  ui_story_31380601_29_dialog_content = "Officer Gronru, I'm here to report on a mission.",
  ui_story_31380601_30_dialog_content = "It's my super-rare researcher, Sio! You came back just in time!",
  ui_story_31380601_31_dialog_content = "About this mission—I was working on it with PlayerName...",
  ui_story_31380601_32_dialog_content = "Say no more. I have read your written report and it's absolutely fine.",
  ui_story_31380601_33_dialog_content = "Now that we're all done with work, why don't we get some gaming in! Yeah!",
  ui_story_31380601_34_dialog_content = "G-Gaming? Erm...",
  ui_story_31380601_35_dialog_content = "(Uh-oh, I think she just triggered Siobhan's gameophobia again.)",
  ui_story_31380601_36_dialog_content = "Let's play some other day. Siobhan still has some other stuff to do today.",
  ui_story_31380601_37_dialog_content = "That's not true, you don't have any other missions to do, right?",
  ui_story_31380601_38_dialog_content = "Or... are you taking part in the concert auditions as well!?",
  ui_story_31380601_39_dialog_content = "Huh!? Well um, yeah, I was just about to sign up.",
  ui_story_31380601_40_dialog_content = "If that's the case, I guess that's the end of that!",
  ui_story_31380601_41_dialog_content = "Go sign up. I suppose I only have you to play games with now, PlayerName.",
  ui_story_31380601_42_dialog_content = "Actually, I just remembered that I have something I should be doing right now too!",
  ui_story_31380601_43_dialog_content = "Don't tell me you want to register too!?",
  ui_story_31380601_44_dialog_content = "Erm, I'm definitely not registering, but it's something related to preparing for the concert.",
  ui_story_31380601_45_dialog_content = "You must be part of the concert sponsor's crew then. Can you take special care of Siobhan and Lilliam for me?",
  ui_story_31380601_46_dialog_content = "Are you asking for personal favors right now?",
  ui_story_31380601_47_dialog_content = "No, but if Siobhan or Lilliam wins, the Research Lab will receive special funding.",
  ui_story_31380601_48_dialog_content = "And with funding, I can develop my own idol games! Hahaha!",
  ui_story_31380601_49_dialog_content = "Doesn't that count as misappropriation of public funds!?",
  ui_story_31380601_50_dialog_content = "Alright, I'll leave you guys to it then!",
  ui_story_31380601_51_dialog_content = "Phew... You really helped me get out of a sticky situation!",
  ui_story_31380601_52_dialog_content = "Don't mention it. I was helping myself out of that mess, too.",
  ui_story_31380601_53_dialog_content = "I know we should go for that drink right now, but I really do have something to take care of.",
  ui_story_31380601_54_dialog_content = "I'm sorry... I'll invite you out next time, alright?",
  ui_story_31380601_55_dialog_content = "Sure, no problem... But what do you need to take care of so suddenly?",
  ui_story_31380601_56_dialog_content = "I'm going to sign up for the concert now.",
  ui_story_31380601_57_dialog_content = "Huh? You weren't just using it as a convenient excuse?",
  ui_story_31380601_58_dialog_content = "I really don't have any work to do at the moment, so why not take advantage of this chance to experience something new?",
  ui_story_31380601_59_dialog_content = "Of course, it's also to prevent someone from forcing me to play games with her.",
  ui_story_31380601_60_dialog_content = "The thing is, I've never taken part in this kind of thing before. I feel nervous.",
  ui_story_31380601_61_dialog_content = "Can you come and find me a little later?",
  ui_story_31380601_62_dialog_content = "Sure, no problem.",
  ui_story_31380601_63_dialog_content = "Siobhan asked me to go backstage to find her... I wonder how her preparations are coming along.",
  ui_story_31380601_64_dialog_content = "Is this it? The door's open—",
  ui_story_31380601_65_dialog_content = "Huh?",
  ui_story_31380601_66_dialog_content = "PlayerName, you came.",
  ui_story_31380601_67_dialog_content = "Ah... S-Siobhan?",
  ui_story_31380601_68_dialog_content = "What's the matter? Don't you think I look fabulous?",
  ui_story_31380601_69_dialog_content = "You look so beautiful that for a moment there I felt my soul leave me.",
  ui_story_31380601_70_dialog_content = "Really? Thanks!",
  ui_story_31380601_71_dialog_content = "As long as you think I look good, I know I have nothing to worry about.",
  ui_story_31380601_72_dialog_content = "But that doesn't mean I can get complacent.",
  ui_story_31380601_73_dialog_content = "I asked you to come because I was hoping you could give me your honest analysis from a rational, neutral, objective standpoint.",
  ui_story_31380601_74_dialog_content = "Analysis? It's just a singing contest, for crying out loud!",
  ui_story_31380601_75_dialog_content = "As a serious academic, I need to channel the spirit of research even when taking part in a singing competition.",
  ui_story_31380601_76_dialog_content = "I even wrote a thesis for this competition.",
  ui_story_31380601_77_dialog_content = "It's an analysis of various factors affecting the competition's outcome—from the stage to the competition system, participants, and other aspects.",
  ui_story_31380601_78_dialog_content = "Let's start with the stage—",
  ui_story_31380601_79_dialog_content = "This is an open-air stage, so the performance will be greatly affected by the weather.",
  ui_story_31380601_80_dialog_content = "If it's windy or it rains, that would put a damper on the performance.",
  ui_story_31380601_81_dialog_content = "Therefore, during the performance, we should fully consider the potential impact of various weather conditions.",
  ui_story_31380601_82_dialog_content = "Next, let's talk about the competition system—",
  ui_story_31380601_83_dialog_content = "The first thing to consider is the audition itself, which can be said to be the most difficult phase.",
  ui_story_31380601_84_dialog_content = "If a single mistake is made during this phase, participants will face elimination, and will receive no further chances to continue taking part.",
  ui_story_31380601_85_dialog_content = "Moreover, many of the participants have already accumulated a certain degree of popularity and a sizeable fan base before the start of the competition.",
  ui_story_31380601_86_dialog_content = "They will enjoy a greater advantage in the competition.",
  ui_story_31380601_87_dialog_content = "So, the most important thing here is to analyze the participants!",
  ui_story_31380601_88_dialog_content = "This table shows an \"idol rating analysis\" for my opponents and myself.",
  ui_story_31380601_89_dialog_content = "It includes singing, dancing, looks, figure, EQ, and IQ, with a max score of 5 for each category.",
  ui_story_31380601_90_dialog_content = "Charon—",
  ui_story_31380601_91_dialog_content = "Singing—5, dancing—5, looks—4, figure—4, EQ—0, IQ—3.",
  ui_story_31380601_92_dialog_content = "A popular candidate to take this competition's top spot.",
  ui_story_31380601_93_dialog_content = "Gothic metal stirs the heart like a raging wave.",
  ui_story_31380601_94_dialog_content = "He has enough of an edge to scare his opponents.",
  ui_story_31380601_95_dialog_content = "His weakness is that his low EQ won't bring him far.",
  ui_story_31380601_96_dialog_content = "Lilliam—",
  ui_story_31380601_97_dialog_content = "Singing: 2, dancing: 2, looks: 4, figure: 3, EQ: 1, IQ: 5.",
  ui_story_31380601_98_dialog_content = "A product of the new generation, they possess a certain novelty in that they go against conventional logic.",
  ui_story_31380601_99_dialog_content = "The glory and dignity of four people (machines) putting it all on the line to awaken their main body...",
  ui_story_31380601_100_dialog_content = "Their weakness is that they're blatantly too robotic.",
  ui_story_31380601_101_dialog_content = "Although some people are crazy about this kind of competitor, they don't have what it takes to win over the general public.",
  ui_story_31380601_102_dialog_content = "Your analysis is so detailed... I'd never have guessed you were new to this kind of thing.",
  ui_story_31380601_103_dialog_content = "Don't forget, I'm a professional researcher!",
  ui_story_31380601_104_dialog_content = "But where did you get all that information about your competitors?",
  ui_story_31380601_105_dialog_content = "Well, I invited the registry staff out for drinks.",
  ui_story_31380601_106_dialog_content = "They ended up telling me everything. Even I was shocked by the amount of info they gave me.",
  ui_story_31380601_107_dialog_content = "I hadn't planned on investigating this so thoroughly...",
  ui_story_31380601_108_dialog_content = "Did you give them a little drop of your favorite drink to loosen their lips?",
  ui_story_31380601_109_dialog_content = "Well, I didn't pry into any personal matters. I only recorded information related to the competition.",
  ui_story_31380601_110_dialog_content = "It's a good thing you're the one who found all this out. If someone else were to get their hands on this information, it could spell bad news for the other participants.",
  ui_story_31380601_111_dialog_content = "Never mind about that—let's continue inspecting the competitor data.",
  ui_story_31380601_112_dialog_content = "I introduced a bunch of competitors to you just now, but the most formidable one is the following—",
  ui_story_31380601_113_dialog_content = "The last and strongest warrior of the Sakura Family!",
  ui_story_31380601_114_dialog_content = "Hiiro!",
  ui_story_31380601_115_dialog_content = "Her specific rating cannot be calculated right now, but you can be sure that her stats are off the charts.",
  ui_story_31380601_116_dialog_content = "The winner of last year's competition, Hiiro, is an astoundingly strong opponent.",
  ui_story_31380601_117_dialog_content = "As sublime as a floating cherry blossom, and as fierce as a roaring dragon.",
  ui_story_31380601_118_dialog_content = "I'm not sure if there's an Aurorian alive who can beat her.",
  ui_story_31380601_119_dialog_content = "I never realized Hiiro was so impressive!",
  ui_story_31380601_120_dialog_content = "So, what are you going to do? Are you going to try to defeat Hiiro?",
  ui_story_31380601_121_dialog_content = "Well, as for me, Siobhan—",
  ui_story_31380601_122_dialog_content = "Singing: 1, dancing: 1, looks: 6, figure: 6, EQ: 5, IQ: 5.",
  ui_story_31380601_123_dialog_content = "Wait. You gave your looks and figure 6 points each?",
  ui_story_31380601_124_dialog_content = "I thought you said the maximum was five points!",
  ui_story_31380601_125_dialog_content = "*Cough* Although I'm not great at singing or dancing, the other four areas should compensate for that.",
  ui_story_31380601_126_dialog_content = "Are you pretending you can't hear me?",
  ui_story_31380601_127_dialog_content = "Never mind, those two scores are objective anyway.",
  ui_story_31380601_128_dialog_content = "Hah!",
  ui_story_31380601_129_dialog_content = "Are you laughing?",
  ui_story_31380601_130_dialog_content = "Anyways... if I give it my all, I'll have a chance of winning this whole thing.",
  ui_story_31380601_131_dialog_content = "But you went a bit hard on yourself in the singing and dancing categories... You only gave one point for each?",
  ui_story_31380601_132_dialog_content = "Do you think you've prepared well enough to make it into the top three?",
  ui_story_31380601_133_dialog_content = "That's another reason I invited you here. There's no way my evaluation of myself could ever be objective enough.",
  ui_story_31380601_134_dialog_content = "Why don't you show me part of your performance and let me give you a score?",
  ui_story_31380601_135_dialog_content = "You want me to perform now? It's so sudden... To be honest, I'm feeling a little shy.",
  ui_story_31380601_136_dialog_content = "But if that's what you want...",
  ui_story_31380601_137_dialog_content = "Okay, let's do this.",
  ui_story_31380601_138_dialog_content = "(Hmm... I know this is only the opening of her performance, but Siobhan's style is not bad at all.)",
  ui_story_31380601_139_dialog_content = "(Light steps, beautiful posture, a beautiful face—she stands a good chance of captivating most people in the audience.)",
  ui_story_31380601_140_dialog_content = "♪ Go to work when I wake up, got no time to eat ♪",
  ui_story_31380601_141_dialog_content = "♪ Too much work to handle, got no time to sleep ♪",
  ui_story_31380601_142_dialog_content = "Hold on, what kind of song is this!?",
  ui_story_31380601_143_dialog_content = "I picked a random rap song from the top charts earlier.",
  ui_story_31380601_144_dialog_content = "I thought it was some kind of heavy metal...",
  ui_story_31380601_145_dialog_content = "Judging from your expression, I suppose I'm not as good as I used to be.",
  ui_story_31380601_146_dialog_content = "You've performed on stage before?",
  ui_story_31380601_147_dialog_content = "When I was very young and living in Undercity 66, I danced in a few group performances.",
  ui_story_31380601_148_dialog_content = "When you were very young!?",
  ui_story_31380601_149_dialog_content = "I was only four or five years old but I still led the troupe.",
  ui_story_31380601_150_dialog_content = "I reckon I could've scored at least a four in singing and dancing back then.",
  ui_story_31380601_151_dialog_content = "But, considering the fact that I haven't practiced in years, I assumed that my skills would've deteriorated quite significantly, so I gave an objective score of one point.",
  ui_story_31380601_152_dialog_content = "Your evaluation of yourself is actually very rational, neutral, and objective.",
  ui_story_31380601_153_dialog_content = "Now it seems that it'll be difficult to win through singing and dancing alone.",
  ui_story_31380601_154_dialog_content = "So, do you think I should add some of my personal talents to my song and dance number?",
  ui_story_31380601_155_dialog_content = "What kind of personal talents?",
  ui_story_31380601_156_dialog_content = "Demolition—",
  ui_story_31380601_157_dialog_content = "I'll make a small smoke bomb that lets off a huge roaring blast...",
  ui_story_31380601_158_dialog_content = "Then I'll emerge from the smoke, giving the audience a nice little surprise.",
  ui_story_31380601_159_dialog_content = "(I don't know if the stage could handle an explosion... If it collapses, that certainly would be a surprise.)",
  ui_story_31380601_160_dialog_content = "Advanced Camouflage—",
  ui_story_31380601_161_dialog_content = "I'll hide among the decor and keep chanting, \"Siobhan is the best,\" to brainwash passers-by.",
  ui_story_31380601_162_dialog_content = "(Is it that easy to brainwash people?)",
  ui_story_31380601_163_dialog_content = "Spider Dance—",
  ui_story_31380601_164_dialog_content = "I'll have my adorable spiders spin webs across the stage, and each little spider will bounce along to the music.",
  ui_story_31380601_165_dialog_content = "They can also wander into the audience to interact with people. Everyone would love that, right?",
  ui_story_31380601_166_dialog_content = "(And if an audience member suffers from arachnophobia, they'll faint on the spot...)",
  ui_story_31380601_167_dialog_content = "And the last one is Precision Dusting.",
  ui_story_31380601_168_dialog_content = "If all else fails, I still have this ace up my sleeve!",
  ui_story_31380601_169_dialog_content = "I've been removing dust from antiques for many years now, and have mastered the unique skill of dusting.",
  ui_story_31380601_170_dialog_content = "If I dust the entire audience, they'll be pleased with me, won't they?",
  ui_story_31380601_171_dialog_content = "(When you suddenly start invading everyone's personal space with your duster, who would be pleased with that!?)",
  ui_story_31380601_172_dialog_content = "I'm getting all flustered! Which skill should I use?",
  ui_story_31380601_173_dialog_content = "PlayerName, can you help me to choose one?",
  ui_story_31380601_174_option_content = "Can I choose none of them?",
  ui_story_31380601_175_dialog_content = "Are they really not suitable for the competition?",
  ui_story_31380601_176_dialog_content = "(Siobhan's head is hanging so low... She looks really hopeless.)",
  ui_story_31380601_177_dialog_content = "Your skills are great, but they're not suitable for a performance like this.",
  ui_story_31380601_178_dialog_content = "Thank you for your candor... and for your kindness.",
  ui_story_31380601_179_option_content = "Just choose the one you like!",
  ui_story_31380601_180_dialog_content = "You think they're all good, right...? So, it's hard to make a choice...?",
  ui_story_31380601_181_dialog_content = "Then I'll use them all to maximize my chances of winning.",
  ui_story_31380601_182_dialog_content = "(I hope nothing bad comes of this.)",
  ui_story_31380601_183_dialog_content = "I really put you through a lot today.",
  ui_story_31380601_184_dialog_content = "It's fine. I actually gained a lot of insight today...",
  ui_story_31380601_185_dialog_content = "Now, I'm going to go all out to prepare for my audition!",
  ui_story_31380601_186_dialog_content = "Good luck!"
}
return config
